import collections

def entities(doc, scope):
    """Extracts all machines, tasks, and jobs from the scope."""
    ents = {}
    nodes = scope_nodes(doc, node_by_title(doc, scope))

    # Extract machines
    machines_node = next((n for n in nodes if n['title'] == f"{scope}: Machines"), None)
    if machines_node:
        for row in table_rows(machines_node):
            mid = row['machine']
            ents[mid] = {"id": mid, "description": f"Machine {mid}"}

    # Extract tasks and jobs
    log_node = next((n for n in nodes if n['title'] == f"{scope}: Task log"), None)
    if log_node:
        for row in table_rows(log_node):
            tid = row['task']
            jid = row['job']
            ents[tid] = {"id": tid, "description": f"Task {tid}"}
            ents[jid] = {"id": jid, "description": f"Job {jid}"}

    return list(ents.values())

def recorded_end(doc, scope):
    """The window length is fixed at 1200 seconds."""
    return 1200.0

def inputs(doc, scope):
    """Extracts machine capacities and task submissions."""
    inputs_list = []
    nodes = scope_nodes(doc, node_by_title(doc, scope))

    # Machines as initial state inputs
    machines_node = next((n for n in nodes if n['title'] == f"{scope}: Machines"), None)
    if machines_node:
        node_id = machines_node['node_id']
        for idx, row in table_rows(machines_node):
            mid = row['machine']
            inputs_list.append({
                "id": f"setup_{mid}",
                "time": 0.0,
                "kind": "machine_setup",
                "entities": [mid],
                "fields": {
                    "cpu": int(row['CPU']),
                    "memory": int(row['memory']),
                    "fails_at": int(row['fails at']) if row['fails at'] != '-' else None,
                    "returns_at": int(row['returns at']) if row['returns at'] != '-' else None
                },
                "src": [[node_id, idx]]
            })

    # Task submissions from log
    log_node = next((n for n in nodes if n['title'] == f"{scope}: Task log"), None)
    if log_node:
        node_id = log_node['node_id']
        for idx, row in table_rows(log_node):
            if row['event'] == 'submit':
                tid = row['task']
                jid = row['job']
                inputs_list.append({
                    "id": f"submit_{tid}",
                    "time": float(row['time']),
                    "kind": "task_submission",
                    "entities": [tid, jid],
                    "fields": {
                        "priority": int(row['priority']),
                        "cpu": int(row['CPU']),
                        "memory": int(row['memory']),
                        "run_time": int(row['run time'])
                    },
                    "src": [[node_id, idx]]
                })

    return inputs_list

def outcomes(doc, scope):
    """Extracts scheduling events (starts, finishes, evictions, fails) and the final queue state."""
    outcomes_list = []
    nodes = scope_nodes(doc, node_by_title(doc, scope))

    # Task events from log
    log_node = next((n for n in nodes if n['title'] == f"{scope}: Task log"), None)
    if log_node:
        node_id = log_node['node_id']
        for idx, row in table_rows(log_node):
            event = row['event']
            if event in ['start', 'finish', 'evict', 'fail']:
                tid = row['task']
                mid = row['machine']
                entities_involved = [tid]
                if mid != '-':
                    entities_involved.append(mid)
                outcomes_list.append({
                    "time": float(row['time']),
                    "kind": f"task_{event}",
                    "entities": entities_involved,
                    "value": None,
                    "src": [[node_id, idx]]
                })

    # Final state from Queue table
    queue_node = next((n for n in nodes if n['title'] == f"{scope}: Queue at window end"), None)
    if queue_node:
        node_id = queue_node['node_id']
        for idx, row in table_rows(queue_node):
            tid = row['task']
            rem = row['remaining']
            # If it's a number, the task is still running (result quantity: remaining time)
            # If it's '-', the task is waiting.
            val = float(rem) if rem != '-' else None
            outcomes_list.append({
                "time": 1200.0,
                "kind": "queue_final_state",
                "entities": [tid],
                "value": val,
                "src": [[node_id, idx]]
            })

    return outcomes_list

def params(doc, scope):
    """Constants mentioned in the document description."""
    return {
        "window_length": 1200,
        "num_machines": 8
    }

